export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/hb2
rm -rf $D; mkdir -p $D; cd $D || exit 1
cat > p.b64 <<'EOS'

EOS
base64 -d p.b64 > p.zip && unzip -oq p.zip -d $D
for t in e0 e1; do
  /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source $t.tcl > $t.log 2>&1
  if grep -q "DONE_$t" $t.log; then echo "OK $t pips=$(wc -l < $t.pips) cmt=$(grep -c HCLK_CMT $t.pips)"; else echo "FAIL $t"; grep -E "ERROR" $t.log | head -4; fi
done
tar czf /tmp/hb2_out.tgz *.bit *.pips *.log 2>/dev/null || true
echo HB2DONE
